            return 'D'
        return 'C'
    if opp_defects == 0:
        if n >= 90:
            return 'D'
        return 'C'
    if recent_defects == recent:
        if recent_op[-1] == 'D' and recent_op[-2] == 'D':
            return 'D'
        return 'D'
    if recent_defects == 0:
        return 'C'
    defection_rate = opp_defects / n
    if defection_rate > 0.5:
        return 'D'
    if defection_rate > 0.25:
        if n % 3 == 0:
            return 'D'
        return 'C'
    if recent_defects >= 2:
        return 'D'
    return 'C'
